import {Button, IconButton} from '@primer/react'
import {CopilotIcon} from '@primer/octicons-react'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {publishOpenCopilotChat} from '@github-ui/copilot-chat/utils/copilot-chat-events'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getFailedActionsJobPrompt} from '@github-ui/copilot-chat/utils/prompts'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {CopilotChatIntents} from '@github-ui/copilot-chat/utils/copilot-chat-types'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {parseJobUrlToReference} from '@github-ui/copilot-chat/utils/job-url-parser'
import styles from './CopilotActionsChatButton.module.css'
import {clsx} from 'clsx'
import {isFeatureEnabled} from '@github-ui/feature-flags'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import {sendEvent} from '@github-ui/hydro-analytics'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {referenceID} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'

const ACTIONS_CHAT_BUTTON_ID = 'copilot-actions-chat-button'
interface CopilotActionsChatButtonProps {
  displayName?: string
}

export function CopilotActionsChatButton({displayName}: CopilotActionsChatButtonProps) {
  const handleAnalyzeFailure = () => {
    const errorRedirectEnabled =
      isFeatureEnabled('copilot_chat_action_logs_redirect') && !isFeatureEnabled('copilot_immersive_embedded')
    if (errorRedirectEnabled) {
      sendEvent('copilot.open_copilot_chat', {source: `element ${ACTIONS_CHAT_BUTTON_ID}`})
      // Create JobReference from current window location
      const jobReference = parseJobUrlToReference(window.location.href, true, displayName)
      const references = jobReference ? [jobReference] : []

      const prompt = getFailedActionsJobPrompt(undefined, true)
      copilotLocalStorage.setEntrypointMessage({message: prompt, references})
      copilotLocalStorage.setCurrentReferences(null, references)
      window.location.href = jobReference ? `/copilot?reference_id=${referenceID(jobReference)}` : '/copilot'
      return
    } else {
      publishOpenCopilotChat({
        intent: CopilotChatIntents.actionsAgent,
        content: getFailedActionsJobPrompt(),
        references: [],
        id: ACTIONS_CHAT_BUTTON_ID,
      })
    }
  }

  return (
    <>
      {/* Compact variant */}
      <IconButton
        className={clsx(styles.copilotActionsChatButton, styles.compact)}
        icon={CopilotIcon}
        aria-label="Explain error"
        style={{boxShadow: 'none'}}
        onClick={handleAnalyzeFailure}
      />

      {/* Expanded variant */}
      <Button
        className={clsx(styles.copilotActionsChatButton, styles.expanded)}
        leadingVisual={CopilotIcon}
        onClick={handleAnalyzeFailure}
        style={{boxShadow: 'none'}}
      >
        Explain error
      </Button>
    </>
  )
}

try{ CopilotActionsChatButton.displayName ||= 'CopilotActionsChatButton' } catch {}